-- FSMVÜ Hukuk Kulübü — Faaliyetler sayfası yönetimi
-- Supabase Dashboard > SQL Editor içinde bu dosyanın tamamını çalıştırın.
-- (001_init.sql daha önce çalıştırılmış olmalı: set_updated_at fonksiyonu oradan gelir.)

-- ---------------------------------------------------------------------------
-- faaliyet_kategorileri — /faaliyetler sayfasındaki filtre çipleri
-- (Seminer, Kurgusal Duruşma, ...). Yönetim panelinden eklenip yeniden
-- adlandırılabilir; "Tümü" çipi sabittir, tabloda tutulmaz.
-- ---------------------------------------------------------------------------
create table if not exists public.faaliyet_kategorileri (
  id          uuid primary key default gen_random_uuid(),
  ad          text not null unique check (length(trim(ad)) > 0),
  sira        integer not null default 0,
  created_at  timestamptz not null default now()
);
create index if not exists faaliyet_kategorileri_sira_idx on public.faaliyet_kategorileri (sira);

-- ---------------------------------------------------------------------------
-- faaliyetler — /faaliyetler listesi, /faaliyetler/:slug detayı ve
-- ana sayfadaki "Son Faaliyetler" bölümü
-- ---------------------------------------------------------------------------
create table if not exists public.faaliyetler (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  baslik        text not null,
  ozet          text not null default '',          -- kart üzerindeki kısa açıklama
  kategori      text not null references public.faaliyet_kategorileri (ad)
                on update cascade on delete restrict,
  tarih         date not null,                      -- yıl / ay filtreleri bu alandan çalışır
  saat          text,                               -- örn. '14:00 – 17:00'
  yer           text,
  katilimci     integer not null default 0 check (katilimci >= 0),
  kapak_url     text,                               -- kart ve detay hero görseli
  icerik        text[] not null default '{}',       -- "Etkinlik Hakkında" paragrafları
  program       text[] not null default '{}',       -- "Neler Yapıldı" adımları
  kazanimlar    text[] not null default '{}',       -- "Katılımcılara Kazandırdıkları"
  konusmacilar  jsonb not null default '[]'::jsonb, -- [{ "ad": "...", "unvan": "..." }]
  galeri        text[] not null default '{}',       -- galeri görsel URL'leri
  yayinda       boolean not null default true,      -- false ise sitede görünmez (taslak)
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists faaliyetler_tarih_idx on public.faaliyetler (tarih desc);
create index if not exists faaliyetler_kategori_idx on public.faaliyetler (kategori);
drop trigger if exists faaliyetler_set_updated_at on public.faaliyetler;
create trigger faaliyetler_set_updated_at before update on public.faaliyetler
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- RLS: ziyaretçiler sadece yayındaki faaliyetleri ve tüm kategorileri görür;
-- giriş yapmış yöneticiler her şeyi yapar.
-- ---------------------------------------------------------------------------
alter table public.faaliyet_kategorileri enable row level security;

drop policy if exists "public select" on public.faaliyet_kategorileri;
create policy "public select" on public.faaliyet_kategorileri for select to anon, authenticated using (true);
drop policy if exists "admin insert" on public.faaliyet_kategorileri;
create policy "admin insert" on public.faaliyet_kategorileri for insert to authenticated with check (true);
drop policy if exists "admin update" on public.faaliyet_kategorileri;
create policy "admin update" on public.faaliyet_kategorileri for update to authenticated using (true) with check (true);
drop policy if exists "admin delete" on public.faaliyet_kategorileri;
create policy "admin delete" on public.faaliyet_kategorileri for delete to authenticated using (true);

alter table public.faaliyetler enable row level security;

drop policy if exists "public select yayinda" on public.faaliyetler;
create policy "public select yayinda" on public.faaliyetler for select to anon using (yayinda = true);
drop policy if exists "admin select" on public.faaliyetler;
create policy "admin select" on public.faaliyetler for select to authenticated using (true);
drop policy if exists "admin insert" on public.faaliyetler;
create policy "admin insert" on public.faaliyetler for insert to authenticated with check (true);
drop policy if exists "admin update" on public.faaliyetler;
create policy "admin update" on public.faaliyetler for update to authenticated using (true) with check (true);
drop policy if exists "admin delete" on public.faaliyetler;
create policy "admin delete" on public.faaliyetler for delete to authenticated using (true);

-- ---------------------------------------------------------------------------
-- Storage: kapak ve galeri görselleri için herkese açık "faaliyetler" bucket'ı.
-- Herkes okuyabilir; sadece giriş yapmış yöneticiler yükler / siler.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('faaliyetler', 'faaliyetler', true, 8388608, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "faaliyetler public read" on storage.objects;
create policy "faaliyetler public read" on storage.objects for select to anon, authenticated
  using (bucket_id = 'faaliyetler');
drop policy if exists "faaliyetler admin insert" on storage.objects;
create policy "faaliyetler admin insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'faaliyetler');
drop policy if exists "faaliyetler admin update" on storage.objects;
create policy "faaliyetler admin update" on storage.objects for update to authenticated
  using (bucket_id = 'faaliyetler') with check (bucket_id = 'faaliyetler');
drop policy if exists "faaliyetler admin delete" on storage.objects;
create policy "faaliyetler admin delete" on storage.objects for delete to authenticated
  using (bucket_id = 'faaliyetler');

-- ---------------------------------------------------------------------------
-- Başlangıç verisi: kategoriler (yoksa eklenir).
-- ---------------------------------------------------------------------------
insert into public.faaliyet_kategorileri (ad, sira)
values ('Seminer', 1), ('Kurgusal Duruşma', 2), ('Zirve', 3), ('Teknik Gezi', 4), ('Sosyal', 5)
on conflict (ad) do nothing;

-- ---------------------------------------------------------------------------
-- Başlangıç verisi: sitede hâlihazırda görünen 13 faaliyet (tablo boşsa eklenir).
-- Görseller geçici Unsplash örnekleridir; yönetim panelinden değiştirin.
-- ---------------------------------------------------------------------------
insert into public.faaliyetler (slug, baslik, ozet, kategori, tarih, saat, yer, katilimci, kapak_url, icerik, program, kazanimlar, konusmacilar, galeri)
select * from (values
  ('anayasa-hukukunda-guncel-gelismeler', 'Anayasa Hukukunda Güncel Gelişmeler', 'Anayasa Mahkemesi raportörlerinin katılımıyla güncel bireysel başvuru içtihatları üzerine seminer.', 'Seminer', date '2025-03-12', '14:00 – 17:00', 'Haliç Yerleşkesi Konferans Salonu', 140, 'https://images.unsplash.com/photo-1589829545856-d10d557cf95f?w=800&q=80', array['Seminerde Anayasa Mahkemesi raportörleri, son dönemde verilen bireysel başvuru kararlarının hukuk eğitimi ve uygulama açısından taşıdığı önemi detaylı biçimde ele aldı. Özellikle adil yargılanma hakkı ve ifade özgürlüğü başlıklarında verilen pilot kararlar üzerinde duruldu.','İkinci oturumda katılımcılar, seçilmiş içtihatlar üzerinden ihlal tespit sürecinin nasıl işlediğini örneklerle inceleme fırsatı buldu. Soru-cevap bölümünde öğrencilerin bireysel başvuru dilekçesi hazırlamaya ilişkin soruları yanıtlandı.']::text[], array['Açılış konuşması ve Anayasa Mahkemesinin yapısına ilişkin genel bilgilendirme','Güncel bireysel başvuru içtihatlarının sunumu','Pilot kararlar ve yapısal sorunların tartışılması','Soru-cevap ve kapanış oturumu']::text[], array['Bireysel başvuru mekanizmasının işleyişine hâkimiyet','Güncel AYM içtihatlarını okuma ve yorumlama becerisi','Başvuru dilekçesinin temel unsurları hakkında pratik bilgi','Anayasa Mahkemesi raportörleriyle doğrudan iletişim imkânı']::text[], '[{"ad":"Dr. Elif Kaya","unvan":"Anayasa Mahkemesi Raportörü"},{"ad":"Arş. Gör. Mert Demir","unvan":"Anayasa Hukuku Araştırma Görevlisi"}]'::jsonb, array['https://images.unsplash.com/photo-1589829545856-d10d557cf95f?w=800&q=80','https://images.unsplash.com/photo-1524178232363-1fb2b075b655?w=800&q=80','https://images.unsplash.com/photo-1521587760476-6c12a4b040da?w=800&q=80']::text[]),
  ('viii-kurgusal-durusma-yarismasi', 'VIII. Kurgusal Duruşma Yarışması', 'Üniversiteler arası kurgusal duruşma yarışmamızın finali Haliç Yerleşkesi konferans salonunda gerçekleşti.', 'Kurgusal Duruşma', date '2025-02-28', '09:30 – 18:00', 'Haliç Yerleşkesi Konferans Salonu', 96, 'https://images.unsplash.com/photo-1589994965851-a8f479c573a9?w=800&q=80', array['Sekizincisini düzenlediğimiz Kurgusal Duruşma Yarışması’nda Türkiye’nin farklı üniversitelerinden 12 takım, ceza hukuku alanındaki kurgusal bir dosya üzerinden iddia ve savunma makamında sözlü sunumlarını gerçekleştirdi. Hakem heyeti alanında deneyimli hakim, savcı ve avukatlardan oluştu.','Final turunda iki takım, heyet karşısında esas hakkındaki mütalaalarını sundu. Yarışma sonunda dereceye giren takımlara ödülleri takdim edilirken, en iyi savunma makamı ve en iyi konuşmacı özel ödülleri de sahiplerini buldu.']::text[], array['Takımların kayıt ve dosya dağılımı','Eleme turları: iddia ve savunma sunumları','Yarı final ve final duruşmaları','Hakem değerlendirmesi ve geri bildirim oturumu','Ödül töreni ve kapanış']::text[], array['Sözlü yargılama ortamında pratik deneyim','Dava dosyası analizi ve hukuki argüman inşa etme becerisi','Hakim ve savcılarla birebir geri bildirim alma fırsatı','Takım çalışması ve sahne hâkimiyeti']::text[], '[{"ad":"Hakim Selim Arslan","unvan":"İstanbul Bölge Adliye Mahkemesi Üyesi"},{"ad":"Av. Deniz Öztürk","unvan":"Ceza Hukuku Uzmanı"},{"ad":"Prof. Dr. Aylin Yıldız","unvan":"Ceza ve Ceza Muhakemesi Hukuku Anabilim Dalı"}]'::jsonb, array['https://images.unsplash.com/photo-1589994965851-a8f479c573a9?w=800&q=80','https://images.unsplash.com/photo-1575505586569-646b2ca898fc?w=800&q=80','https://images.unsplash.com/photo-1505373877841-8d25f7d46678?w=800&q=80']::text[]),
  ('genc-hukukcular-zirvesi', 'Genç Hukukçular Zirvesi', 'Türkiye genelinden hukuk kulüplerinin katıldığı, kariyer ve staj odaklı yıllık zirvemiz.', 'Zirve', date '2025-02-15', '10:00 – 17:30', 'Haliç Yerleşkesi Amfi 1', 210, 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800&q=80', array['Bu yıl beşincisini düzenlediğimiz Genç Hukukçular Zirvesi, 20’yi aşkın üniversiteden hukuk öğrencisi kulübünü aynı çatı altında buluşturdu. Zirvede kariyer planlama, staj başvuruları ve uluslararası alanda hukukçu olmak başlıklı üç panel gerçekleşti.','Panel aralarında düzenlenen kulüpler arası tanışma oturumlarında katılımcılar, ortak proje ve iş birliği fırsatlarını değerlendirdi. Zirve, kapanış konuşması ve katılım sertifikalarının dağıtımıyla sona erdi.']::text[], array['Açılış konuşmaları ve katılımcı kulüplerin tanıtımı','Panel I: Hukuk fakültesinde kariyer planlama','Panel II: Staj ve kurumsal hukuk deneyimi','Panel III: Uluslararası kariyer yolları','Kulüpler arası networking oturumu']::text[], array['Farklı kariyer yollarını doğrudan hukukçulardan dinleme imkânı','Diğer üniversitelerin hukuk kulüpleriyle network kurma','CV ve staj başvurusu hazırlarken dikkat edilmesi gerekenler','Kulüpler arası ortak etkinlik fikirleri']::text[], '[{"ad":"Av. Begüm Şen","unvan":"Kurumsal Hukuk Direktörü"},{"ad":"Av. Kaan Yücel","unvan":"Uluslararası Tahkim Avukatı"}]'::jsonb, array['https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800&q=80','https://images.unsplash.com/photo-1591115765373-5207764f72e7?w=800&q=80','https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800&q=80']::text[]),
  ('caglayan-adliyesi-teknik-gezisi', 'Çağlayan Adliyesi Teknik Gezisi', 'İstanbul Adalet Sarayı duruşma salonları ve adliye birimlerine düzenlenen teknik gezi.', 'Teknik Gezi', date '2025-01-20', '10:00 – 13:00', 'İstanbul Adalet Sarayı, Çağlayan', 45, 'https://images.unsplash.com/photo-1479142506502-19b3a3b7ff33?w=800&q=80', array['İstanbul Adalet Sarayı’na düzenlediğimiz teknik gezide öğrenciler, duruşma salonlarının fiziksel düzenini ve bir duruşma gününün işleyişini yerinde gözlemledi. Adliye yazı işleri müdürlüğü ve icra birimleri de ziyaret programı kapsamında gezildi.','Gezi sırasında görevli bir hakim, duruşma öncesi ve sonrası süreçler hakkında öğrencilerin sorularını yanıtladı. Katılımcılar, dava dosyalarının adliyedeki yolculuğunu uygulamalı olarak takip etme fırsatı yakaladı.']::text[], array['Adliye ana girişinde buluşma ve güvenlik geçişi','Ağır ceza ve asliye duruşma salonlarının ziyareti','Yazı işleri ve icra birimlerinin gezilmesi','Hakim ile sohbet oturumu ve soru-cevap']::text[], array['Adliye teşkilatının işleyişini yerinde görme','Duruşma düzeni ve adli süreçler hakkında gözlem','Dava dosyasının fiziki akışını anlama','Adliye birimlerinin görev dağılımı hakkında bilgi']::text[], '[]'::jsonb, array['https://images.unsplash.com/photo-1479142506502-19b3a3b7ff33?w=800&q=80','https://images.unsplash.com/photo-1568667256549-094345857637?w=800&q=80','https://images.unsplash.com/photo-1436450412740-6b988f486c6b?w=800&q=80']::text[]),
  ('yil-sonu-hukuk-bulusmasi', 'Yıl Sonu Hukuk Buluşması', 'Mezunlarımız ve üyelerimizin katıldığı geleneksel yıl sonu sosyal buluşması.', 'Sosyal', date '2024-12-27', '18:00 – 22:00', 'Haliç Yerleşkesi Sosyal Tesisleri', 120, 'https://images.unsplash.com/photo-1511578314322-379afb476865?w=800&q=80', array['Geleneksel yıl sonu buluşmamızda mezunlarımız ve aktif üyelerimiz bir araya geldi. Gecede kulübün yıl içinde gerçekleştirdiği faaliyetlerin kısa bir sunumu yapıldı ve yeni dönem projeleri tanıtıldı.','Sohbet ve müzik eşliğinde süren buluşmada mezunlar, meslek hayatına dair tecrübelerini öğrenci arkadaşlarıyla paylaştı. Etkinlik, çekiliş ve hatıra fotoğrafı çekimiyle sona erdi.']::text[], array['Karşılama ve kayıt','Yıl değerlendirme sunumu ve yeni dönem tanıtımı','Mezun-öğrenci sohbet masaları','Çekiliş ve kapanış']::text[], array['Mezunlarla samimi ortamda tanışma ve network','Kulüp faaliyetlerinin yıl sonu değerlendirmesi','Yeni dönem projelerine erken dahil olma fırsatı']::text[], '[]'::jsonb, array['https://images.unsplash.com/photo-1511578314322-379afb476865?w=800&q=80','https://images.unsplash.com/photo-1543269865-cbf427effbad?w=800&q=80','https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800&q=80']::text[]),
  ('ceza-hukukunda-yargilama-pratigi', 'Ceza Hukukunda Yargılama Pratiği', 'Deneyimli ceza hakimlerinin pratik tecrübelerini aktardığı uygulamalı seminer.', 'Seminer', date '2024-12-10', '14:00 – 16:30', 'Haliç Yerleşkesi Amfi 2', 110, 'https://images.unsplash.com/photo-1505664194779-8beaceb93744?w=800&q=80', array['Seminerde görev yapan ceza hakimleri, yargılama pratiğinde karşılaşılan güncel sorunları ve iyi uygulama örneklerini paylaştı. Delil değerlendirmesi ve gerekçeli karar yazımı başlıkları katılımcıların en çok ilgi gösterdiği konular oldu.','Uygulama bölümünde örnek bir iddianame ve duruşma tutanağı üzerinden tartışma yürütüldü. Öğrenciler, teorik bilgilerinin pratikte nasıl şekillendiğini ilk elden dinleme imkânı buldu.']::text[], array['Ceza yargılamasında temel ilkelerin hatırlatılması','Delil toplama ve değerlendirme pratikleri','Gerekçeli karar yazımı üzerine uygulamalı örnek','Soru-cevap ve kapanış']::text[], array['Duruşma pratiğine ilişkin gerçek deneyim aktarımı','Delil değerlendirmesinde hakim bakış açısını kavrama','Gerekçeli karar mantığını anlama']::text[], '[{"ad":"Hakim Murat Koç","unvan":"Ağır Ceza Mahkemesi Başkanı"},{"ad":"Hakim Seda Ünal","unvan":"Asliye Ceza Mahkemesi Hakimi"}]'::jsonb, array['https://images.unsplash.com/photo-1505664194779-8beaceb93744?w=800&q=80','https://images.unsplash.com/photo-1436450412740-6b988f486c6b?w=800&q=80','https://images.unsplash.com/photo-1521587760476-6c12a4b040da?w=800&q=80']::text[]),
  ('tbmm-ziyareti', 'TBMM Ziyareti', 'Türkiye Büyük Millet Meclisi Genel Kurul salonu ve komisyon toplantılarına katılım.', 'Teknik Gezi', date '2024-11-22', '09:00 – 15:00', 'TBMM, Ankara', 40, 'https://images.unsplash.com/photo-1523292562811-8fa7962a78c8?w=800&q=80', array['Ankara’ya düzenlediğimiz günübirlik teknik gezide öğrenciler, TBMM Genel Kurul salonunu ve Meclis tarihine ayrılmış bölümleri rehber eşliğinde gezdi. Kanun yapım sürecinin aşamaları, komisyon çalışmaları ve yasama faaliyetlerinin işleyişi hakkında bilgi verildi.','Ziyaretin ikinci bölümünde öğrenciler, mümkün olan bir komisyon toplantısını izleme ve milletvekili danışmanlarıyla sohbet etme fırsatı yakaladı.']::text[], array['Ankara’ya hareket ve Meclis’e giriş','Genel Kurul salonu ve tarihi bölümlerin gezilmesi','Kanun yapım süreci üzerine bilgilendirme sunumu','Komisyon toplantısı izleme ve değerlendirme']::text[], array['Yasama sürecini yerinde gözlemleme','Meclis çalışma düzeni hakkında uygulamalı bilgi','Milletvekili danışmanlarıyla tanışma ve soru sorma']::text[], '[]'::jsonb, array['https://images.unsplash.com/photo-1523292562811-8fa7962a78c8?w=800&q=80','https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&q=80','https://images.unsplash.com/photo-1479142506502-19b3a3b7ff33?w=800&q=80']::text[]),
  ('hukuk-ve-teknoloji-zirvesi', 'Hukuk ve Teknoloji Zirvesi', 'Yapay zekâ, kişisel verilerin korunması ve hukukun dijital dönüşümü üzerine paneller.', 'Zirve', date '2024-11-08', '10:00 – 16:30', 'Haliç Yerleşkesi Amfi 1', 180, 'https://images.unsplash.com/photo-1555374018-13a8994ab246?w=800&q=80', array['Hukuk ve Teknoloji Zirvesi’nde yapay zekânın hukuk pratiğine etkileri, KVKK kapsamındaki güncel yükümlülükler ve hukuk bürolarının dijital dönüşümü konuşuldu. Bilişim hukuku alanında çalışan akademisyen ve avukatlar üç ayrı panelde deneyimlerini paylaştı.','Zirvenin en ilgi çeken oturumu, üretken yapay zekâ araçlarının sözleşme hazırlama ve içtihat araştırmasındaki kullanımı üzerine gerçekleşti. Katılımcılar panel sonrası networking bölümünde konuşmacılarla birebir görüşme imkânı buldu.']::text[], array['Panel I: Yapay zekâ ve hukuk pratiği','Panel II: Kişisel verilerin korunması ve KVKK güncellemeleri','Panel III: Hukuk bürolarında dijital dönüşüm','Networking oturumu ve kapanış']::text[], array['Bilişim hukuku alanının güncel tartışmalarına vâkıf olma','Yapay zekâ araçlarının hukuk eğitimindeki yerini değerlendirme','KVKK yükümlülükleri hakkında temel farkındalık','Alanın önde gelen isimleriyle tanışma']::text[], '[{"ad":"Doç. Dr. Ebru Aksoy","unvan":"Bilişim Hukuku Anabilim Dalı"},{"ad":"Av. Emre Tuncer","unvan":"Teknoloji ve Veri Koruma Hukuku Uzmanı"},{"ad":"Dr. Leyla Erden","unvan":"Kişisel Verileri Koruma Uzmanı"}]'::jsonb, array['https://images.unsplash.com/photo-1555374018-13a8994ab246?w=800&q=80','https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800&q=80','https://images.unsplash.com/photo-1591115765373-5207764f72e7?w=800&q=80']::text[]),
  ('tanisma-kahvaltisi', 'Tanışma Kahvaltısı', 'Yeni üyelerimizle tanıştığımız dönem açılışı kahvaltı organizasyonu.', 'Sosyal', date '2024-10-18', '10:00 – 12:30', 'Haliç Yerleşkesi Bahçe Alanı', 85, 'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800&q=80', array['Güz döneminin açılışını yaptığımız tanışma kahvaltısında yeni üyelerimizle bir araya geldik. Yönetim kurulu üyelerimiz kulübün yapısını, faaliyet takvimini ve alt komisyonlara katılım süreçlerini tanıttı.','Kahvaltı sonrası düzenlenen tanışma oyunlarıyla üyeler birbirini yakından tanıma fırsatı buldu. Etkinlik sonunda ilgi duyan üyeler, komisyonlara göre gruplara kaydedildi.']::text[], array['Karşılama ve kahvaltı','Kulüp tanıtımı ve faaliyet takviminin paylaşılması','Tanışma oyunları','Komisyon kayıtları ve kapanış']::text[], array['Kulüp üyeleri ve yönetimle tanışma ortamı','Komisyonlara dahil olarak dönem içinde aktif rol alma','Yeni dönem faaliyet planından ilk elden haberdar olma']::text[], '[]'::jsonb, array['https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800&q=80','https://images.unsplash.com/photo-1543269865-cbf427effbad?w=800&q=80','https://images.unsplash.com/photo-1511578314322-379afb476865?w=800&q=80']::text[]),
  ('medeni-hukukta-sozlesme-ozgurlugu', 'Medeni Hukukta Sözleşme Özgürlüğü', 'Sözleşme özgürlüğünün sınırları ve genel işlem koşulları üzerine akademik seminer.', 'Seminer', date '2024-05-15', '14:00 – 16:00', 'Haliç Yerleşkesi Seminer Salonu', 95, 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&q=80', array['Medeni hukuk alanında çalışan akademisyenlerin katıldığı seminerde, sözleşme özgürlüğünün anayasal ve yasal sınırları ile genel işlem koşullarının geçerlilik rejimi ele alındı. Tüketici sözleşmelerindeki güncel uyuşmazlıklar örnek kararlarla tartışıldı.','Seminerin ikinci bölümünde katılımcılar, örnek bir sözleşme metni üzerinden geçersizlik hallerini tespit etmeye yönelik grup çalışması yaptı.']::text[], array['Sözleşme özgürlüğünün teorik çerçevesi','Genel işlem koşulları ve geçersizlik halleri','Örnek sözleşme üzerinden grup çalışması','Değerlendirme ve soru-cevap']::text[], array['Sözleşme hukukunun pratik uyuşmazlık alanlarını tanıma','Genel işlem koşulu denetimine ilişkin temel bilgi','Gerçek sözleşme metni analiz deneyimi']::text[], '[{"ad":"Prof. Dr. Hasan İleri","unvan":"Medeni Hukuk Anabilim Dalı"}]'::jsonb, array['https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&q=80','https://images.unsplash.com/photo-1524178232363-1fb2b075b655?w=800&q=80','https://images.unsplash.com/photo-1521587760476-6c12a4b040da?w=800&q=80']::text[]),
  ('vii-kurgusal-durusma-yarismasi', 'VII. Kurgusal Duruşma Yarışması', 'Medeni hukuk konulu yedinci kurgusal duruşma yarışmamızın final turu.', 'Kurgusal Duruşma', date '2024-04-19', '09:30 – 17:00', 'Haliç Yerleşkesi Konferans Salonu', 88, 'https://images.unsplash.com/photo-1575505586569-646b2ca898fc?w=800&q=80', array['Yedinci Kurgusal Duruşma Yarışması’nda takımlar, haksız fiil ve tazminat hukukuna ilişkin kurgusal dosyayı davacı ve davalı vekili sıfatıyla savundu. Hakem heyeti, öğretim üyeleri ve davetli avukatlardan oluştu.','Final turunda takımların yazılı beyanları ve sözlü sunumları ayrı ayrı puanlandı. Yarışma, dereceye giren takımların ve en iyi konuşmacının açıklanmasıyla sona erdi.']::text[], array['Dosya dağılımı ve hazırlık oturumu','Eleme turları','Final duruşması','Ödül töreni']::text[], array['Medeni usulde dilekçe ve sözlü argüman deneyimi','Tazminat hukuku dosyası üzerinde çalışma pratiği','Jüri önünde sunum ve ikna becerisi']::text[], '[{"ad":"Av. Nihan Koral","unvan":"Tazminat Hukuku Uzmanı"},{"ad":"Dr. Öğr. Üyesi Cem Bal","unvan":"Medeni Usul ve İcra-İflas Hukuku"}]'::jsonb, array['https://images.unsplash.com/photo-1575505586569-646b2ca898fc?w=800&q=80','https://images.unsplash.com/photo-1589994965851-a8f479c573a9?w=800&q=80','https://images.unsplash.com/photo-1505373877841-8d25f7d46678?w=800&q=80']::text[]),
  ('kariyer-sohbetleri-yilbasi-bulusmasi', 'Kariyer Sohbetleri ve Yılbaşı Buluşması', 'Mezun hukukçularla kariyer sohbetleri ve yılbaşı temalı sosyal buluşma.', 'Sosyal', date '2023-12-22', '17:00 – 21:00', 'Haliç Yerleşkesi Sosyal Tesisleri', 75, 'https://images.unsplash.com/photo-1543269865-cbf427effbad?w=800&q=80', array['Yılbaşı temalı buluşmamızda farklı alanlarda çalışan mezunlarımız, meslek hayatına geçiş süreçlerini ve kariyer yolculuklarını öğrencilerle paylaştı. Hakimlik, avukatlık ve akademi yollarını seçen konuklar ayrı sohbet masalarında soruları yanıtladı.','Sohbetlerin ardından müzik ve ikramlar eşliğinde sosyal bölüme geçildi; yeni yıl dilekleriyle etkinlik tamamlandı.']::text[], array['Açılış ve konuk takdimi','Mezunlarla masa başı kariyer sohbetleri','Yılbaşı ikramı ve sosyal bölüm','Kapanış ve hatıra fotoğrafı']::text[], array['Farklı meslek yollarını mezunlardan dinleme','Samimi ortamda kariyer soruları sorma fırsatı','Kulüp içi sosyal bağların güçlenmesi']::text[], '[]'::jsonb, array['https://images.unsplash.com/photo-1543269865-cbf427effbad?w=800&q=80','https://images.unsplash.com/photo-1511578314322-379afb476865?w=800&q=80','https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800&q=80']::text[]),
  ('anayasa-mahkemesi-yargitay-gezisi', 'Anayasa Mahkemesi ve Yargıtay Gezisi', 'Ankara’daki yüksek yargı kurumlarına düzenlenen günübirlik teknik gezi.', 'Teknik Gezi', date '2023-10-27', '08:00 – 17:00', 'Anayasa Mahkemesi ve Yargıtay, Ankara', 38, 'https://images.unsplash.com/photo-1568667256549-094345857637?w=800&q=80', array['Günübirlik gezimizde öğrenciler önce Anayasa Mahkemesi’ni ziyaret ederek Genel Kurul salonunu ve bireysel başvuru bürosunun çalışma düzenini inceledi. Kurum görevlileri, başvuru inceleme sürecinin aşamalarını anlattı.','Öğleden sonra Yargıtay’a geçen grup, dairelerin işleyişi ve temyiz incelemesi süreci hakkında bilgi aldı. Gezi, kurum bahçesinde çekilen hatıra fotoğrafıyla tamamlandı.']::text[], array['Ankara’ya hareket ve Anayasa Mahkemesi’ne giriş','Genel Kurul salonu ve bireysel başvuru birimi ziyareti','Yargıtay ziyareti ve daire çalışmaları hakkında bilgilendirme','Değerlendirme ve dönüş']::text[], array['Yüksek yargı kurumlarının çalışma düzenini yerinde görme','Bireysel başvuru ve temyiz süreçleri hakkında uygulamalı bilgi','Yargı mensuplarıyla yüz yüze iletişim']::text[], '[]'::jsonb, array['https://images.unsplash.com/photo-1568667256549-094345857637?w=800&q=80','https://images.unsplash.com/photo-1589829545856-d10d557cf95f?w=800&q=80','https://images.unsplash.com/photo-1436450412740-6b988f486c6b?w=800&q=80']::text[])
) as v(slug, baslik, ozet, kategori, tarih, saat, yer, katilimci, kapak_url, icerik, program, kazanimlar, konusmacilar, galeri)
where not exists (select 1 from public.faaliyetler);
